'use client'
import { useSignal, useSignals, cn } from '@cascivo/core'
import { useRef } from 'react'
import type { HTMLAttributes } from 'react'
import { t, builtin } from '@cascivo/i18n'
import styles from './otp-input.module.css'

export interface OtpInputProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange'> {
  /**
   * Number of input cells.
   *
   * @defaultValue `6`
   * @see the component manifest
   */
  length?: number
  value: string
  onValueChange: (v: string) => void
  /**
   * When true, disables the control and removes it from the tab order.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  disabled?: boolean
  type?: 'numeric' | 'alphanumeric'
}

export function OtpInput({
  length = 6,
  value,
  onValueChange,
  disabled = false,
  type = 'numeric',
  className,
  ...props
}: OtpInputProps) {
  useSignals()
  const slots = useSignal<string[]>(Array.from({ length }, (_, i) => value[i] ?? ''))
  const inputRefs = useRef<Array<HTMLInputElement | null>>([])

  // Sync controlled value into slots during render
  const newSlots = Array.from({ length }, (_, i) => value[i] ?? '')
  if (JSON.stringify(slots.value) !== JSON.stringify(newSlots)) {
    slots.value = newSlots
  }

  function notifyChange(updatedSlots: string[]) {
    onValueChange(updatedSlots.join(''))
    slots.value = updatedSlots
  }

  function focusSlot(index: number) {
    const clamped = Math.max(0, Math.min(length - 1, index))
    inputRefs.current[clamped]?.focus()
  }

  function handleInput(index: number, char: string) {
    const pattern = type === 'numeric' ? /^\d$/ : /^[a-zA-Z0-9]$/
    if (!pattern.test(char)) return
    const updated = [...slots.value]
    updated[index] = char
    notifyChange(updated)
    if (index < length - 1) focusSlot(index + 1)
  }

  function handleKeyDown(index: number, e: React.KeyboardEvent<HTMLInputElement>) {
    if (e.key === 'Backspace') {
      e.preventDefault()
      const updated = [...slots.value]
      if (updated[index]) {
        updated[index] = ''
        notifyChange(updated)
      } else if (index > 0) {
        updated[index - 1] = ''
        notifyChange(updated)
        focusSlot(index - 1)
      }
    } else if (e.key === 'ArrowLeft') {
      e.preventDefault()
      focusSlot(index - 1)
    } else if (e.key === 'ArrowRight') {
      e.preventDefault()
      focusSlot(index + 1)
    }
  }

  function handlePaste(index: number, e: React.ClipboardEvent) {
    const pasted = e.clipboardData
      .getData('text')
      .replace(/\s/g, '')
      .slice(0, length - index)
    const pattern = type === 'numeric' ? /^\d+$/ : /^[a-zA-Z0-9]+$/
    // Only intercept when there is valid content to distribute. Leaving empty
    // or invalid pastes to the default action keeps the field paste-friendly
    // (and avoids tripping the "prevents pasting" best-practices audit).
    if (!pattern.test(pasted)) return
    e.preventDefault()
    const updated = [...slots.value]
    for (let i = 0; i < pasted.length; i++) {
      if (index + i < length) updated[index + i] = pasted[i] ?? ''
    }
    notifyChange(updated)
    focusSlot(Math.min(index + pasted.length, length - 1))
  }

  const ariaLabel = t(builtin.otpInput.label)

  return (
    <div
      className={cn(styles['wrapper'], className)}
      role="group"
      aria-label={ariaLabel}
      {...props}
    >
      {slots.value.map((slot, i) => (
        <input
          key={i}
          ref={(el) => {
            inputRefs.current[i] = el
          }}
          type={type === 'numeric' ? 'tel' : 'text'}
          inputMode={type === 'numeric' ? 'numeric' : 'text'}
          className={styles['slot']}
          value={slot}
          maxLength={1}
          aria-label={t(builtin.otpInput.digit, { n: String(i + 1) })}
          autoComplete={i === 0 ? 'one-time-code' : 'off'}
          disabled={disabled}
          data-filled={slot ? '' : undefined}
          onChange={(e) => {
            const val = e.currentTarget.value.slice(-1)
            if (val) handleInput(i, val)
          }}
          onKeyDown={(e) => handleKeyDown(i, e)}
          onPaste={(e) => handlePaste(i, e)}
          onFocus={(e) => e.currentTarget.select()}
        />
      ))}
    </div>
  )
}

@layer cascivo.component {
  .wrapper {
    /* A grid/flex item's default minimum is its content size, so a control with an
       intrinsic width (an <input> defaults to ~20ch) refuses to shrink and spills out of
       its track — reported as "Input overflows its grid cell" inside <Grid cols={{md:2}}>. */
    min-inline-size: 0;
    display: flex;
    gap: var(--cascivo-space-2);
    align-items: center;
  }

  .slot {
    /* 2.75rem each, but shrinking to share a narrow container: six cells and their gaps are
       304px, more than a 320px screen leaves inside a padded card. */
    flex: 0 1 2.75rem;
    inline-size: 2.75rem;
    min-inline-size: 0;
    height: 3rem;
    font-family: var(--cascivo-font-mono, var(--cascivo-font-sans));
    font-size: var(--cascivo-text-xl);
    font-weight: var(--cascivo-font-semibold);
    text-align: center;
    color: var(--cascivo-color-text);
    background-color: var(--cascivo-color-surface);
    border: 1.5px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-field);
    transition:
      border-color var(--cascivo-duration-150) var(--cascivo-ease-out),
      box-shadow var(--cascivo-duration-150) var(--cascivo-ease-out);
    outline: none;
    caret-color: transparent;

    &:hover:not(:disabled) {
      border-color: var(--cascivo-color-border-strong);
    }

    &:focus {
      border-color: var(--cascivo-color-accent);
      box-shadow: var(--cascivo-focus-ring);
    }

    &[data-filled] {
      border-color: var(--cascivo-color-border-strong);
      background-color: var(--cascivo-color-bg-subtle);
    }

    &:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'OtpInput',
  description: 'Segmented one-time code input',
  category: 'inputs',
  // Six native inputs render, so the code can be typed and submitted; JS adds auto-advance
  // and paste splitting.
  clientJs: 'enhancement',
  states: ['idle', 'focused', 'filled', 'disabled'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'length',
      description: 'Number of input cells.',
      type: 'number',
      required: false,
      default: '6',
    },
    { name: 'value', description: 'The controlled value.', type: 'string', required: true },
    {
      name: 'onValueChange',
      description: 'Called with the new value when it changes.',
      type: '(v: string) => void',
      required: true,
    },
    {
      name: 'disabled',
      description: 'When true, disables the control and removes it from the tab order.',
      type: 'boolean',
      required: false,
      default: 'false',
    },
    {
      name: 'type',
      description: "Accepted characters ('numeric' | 'alphanumeric').",
      type: "'numeric' | 'alphanumeric'",
      required: false,
      default: 'numeric',
    },
  ],
  tokens: [
    '--cascivo-color-surface',
    '--cascivo-color-border',
    '--cascivo-color-accent',
    '--cascivo-color-bg-subtle',
    '--cascivo-radius-input',
    '--cascivo-focus-ring',
  ],
  accessibility: {
    role: 'group',
    wcag: '2.2-AA',
    keyboard: ['ArrowLeft', 'ArrowRight', 'Backspace'],
  },
  examples: [
    { title: 'Basic', code: '<OtpInput value="" onValueChange={() => {}} />' },
    { title: '4-digit', code: '<OtpInput length={4} value="" onValueChange={() => {}} />' },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['form', 'otp', 'code', 'input', 'verification'],
  intent: {
    whenToUse: [
      'Entering a fixed-length one-time code (2FA, SMS verification, email confirmation) split across per-character slots',
      'Codes that benefit from auto-advance between slots and pasting the full code at once',
      'Numeric or alphanumeric short codes of a known length',
    ],
    whenNotToUse: [
      'Variable-length or free-form text — use Input',
      'Secret credentials that should be masked — use PasswordInput',
      'Long codes where per-character boxes add no value over a single field — use Input',
    ],
    antiPatterns: [
      {
        bad: '<Input maxLength={6} placeholder="Enter code" />',
        good: '<OtpInput length={6} value={code} onValueChange={setCode} />',
        why: 'OtpInput gives per-digit slots with auto-advance, backspace-to-previous, full-code paste handling, and autoComplete="one-time-code" that a single Input does not',
      },
    ],
    related: [
      {
        name: 'Input',
        relationship: 'alternative',
        reason: 'Use for variable-length or non-code text entry',
      },
      {
        name: 'PasswordInput',
        relationship: 'alternative',
        reason: 'Use when the entered value is a secret that must be masked',
      },
    ],
    a11yRationale:
      'Wraps the slots in role="group" with a localized aria-label and labels each slot with its position so screen readers announce which digit is being entered; the first slot carries autoComplete="one-time-code" so platform SMS autofill can populate the code.',
    flexibility: [
      {
        area: 'token names',
        level: 'strict',
        note: 'Slot styling must resolve to the listed --cascivo-* tokens',
      },
      {
        area: 'length and type',
        level: 'flexible',
        note: 'length and numeric/alphanumeric type are free to match the issued code format',
      },
    ],
  },
}
